import "./styles.css";

import { playAudio } from "@api/AudioPlayer";
import { NavContextMenuPatchCallback } from "@api/ContextMenu";
import { definePluginSettings } from "@api/Settings";
import { Button } from "@components/Button";
import { Devs } from "@utils/constants";
import { classNameFactory } from "@utils/css";
import { t } from "@utils/esharqI18n";
import definePlugin, { OptionType } from "@utils/types";
import { findComponentByCodeLazy } from "@webpack";
import { Constants, GuildStore, IconUtils, MediaEngineStore, Menu, RestAPI, SearchableSelect, SelectedChannelStore, TextInput, Toasts } from "@webpack/common";

const cl = classNameFactory("vc-exitsounds-");

const PlayIcon = findComponentByCodeLazy("4.96v14.08c0");

function GuildSelector() {
    const { soundGuildId } = settings.use(["soundGuildId"]);
    const options = Object.values(GuildStore.getGuilds()).map(g => ({
        value: g.id,
        label: g.name
    }));

    return (
        <SearchableSelect
            options={options}
            value={options.find(o => o.value === soundGuildId)?.value}
            placeholder={t("اختر خادماً...", "Select a server...")}
            maxVisibleItems={6}
            closeOnSelect={true}
            onChange={v => settings.store.soundGuildId = v}
            renderOptionPrefix={o => {
                const guild = GuildStore.getGuild(o?.value);
                if (!guild?.icon) return null;
                return (
                    <img
                        className={cl("guild-icon")}
                        src={IconUtils.getGuildIconURL({ id: guild.id, icon: guild.icon, size: 32 })!}
                    />
                );
            }}
        />
    );
}

function SoundIdInput() {
    const { soundId } = settings.use(["soundId"]);

    return (
        <div className={cl("input-row")}>
            <div className={cl("input-wrapper")}>
                <TextInput
                    value={soundId}
                    onChange={v => settings.store.soundId = v}
                    placeholder={t("أدخل معرّف الصوت...", "Enter sound ID...")}
                />
            </div>
            <Button
                onClick={() => playAudio(`https://${window.GLOBAL_ENV.CDN_HOST}/soundboard-sounds/${soundId}`, { volume: 50 })}
                disabled={!soundId}
            >
                <PlayIcon color="currentColor" />
            </Button>
        </div>
    );
}

const settings = definePluginSettings({
    soundGuildId: {
        type: OptionType.COMPONENT,
        get description() { return t("اختر السيرفر الذي يحتوي الصوت.", "Select the server that contains the sound."); },
        component: GuildSelector
    },
    soundId: {
        type: OptionType.COMPONENT,
        get description() { return t("أدخل معرّف الصوت الذي تريد تشغيله.", "Enter the ID of the sound you want to play."); },
        component: SoundIdInput
    }
});

const SoundButtonContext: NavContextMenuPatchCallback = (children, { sound }: { sound: { soundId: string; guildId: string; }; }) => {
    children.splice(1, 0,
        <Menu.MenuGroup>
            <Menu.MenuItem
                id="set-global-exit-sound"
                label={t("تعيين كصوت خروج عام", "Set as global exit sound")}
                action={() => {
                    settings.store.soundGuildId = sound.guildId;
                    settings.store.soundId = sound.soundId;
                }}
            />
        </Menu.MenuGroup>
    );
};

export default definePlugin({
    name: "ExitSounds",
    description: "Plays soundboard sounds when disconnecting from voice.",
    tags: ["Fun", "Voice"],
    authors: [Devs.prism],
    dependencies: ["AudioPlayerAPI"],
    settings,
    contextMenus: {
        "sound-button-context": SoundButtonContext
    },
    patches: [
        {
            find: 'type:"VOICE_CHANNEL_SHOW_FEEDBACK"',
            replacement: {
                match: /disconnect\(\)\{/,
                replace: "async $& await $self.onDisconnect();"
            }
        }
    ],
    async onDisconnect() {
        const { soundGuildId, soundId } = settings.store;
        if (!soundGuildId || !soundId || MediaEngineStore.isDeaf()) return;

        const voiceId = SelectedChannelStore.getVoiceChannelId();
        if (!voiceId) return;

        try {
            await RestAPI.post({
                url: Constants.Endpoints.SEND_SOUNDBOARD_SOUND(voiceId),
                body: {
                    sound_id: soundId,
                    source_guild_id: soundGuildId
                }
            });
        } catch {
            Toasts.show({
                message: t("عذراً! حدث خطأ ما.", "Oops! Something went wrong."),
                id: Toasts.genId(),
                type: Toasts.Type.FAILURE
            });
        }
    }
});
