interface clientData {
    name: string;
    version?: string | null | undefined;
    info?: string | boolean | null | undefined;
    spoofed?: string | null | undefined;
    shortHash?: string | null | undefined;
    hash?: string | null | undefined;
    dev?: boolean | null | undefined;
}

async function forceUpdate() {
    const outdated = await checkForUpdates();
    if (outdated) {
        await update();
        relaunch();
    }

    return outdated;
}

export function detectClient(): clientData {
    if (IS_DISCORD_DESKTOP) {
        return {
            name: "Discord Desktop",
            version: DiscordNative.app.getVersion(),
        };
    }
    if (IS_VESKTOP) return {
        name: "Vesktop",
        version: VesktopNative.app.getVersion(),
    };

    if (IS_EQUIBOP) {
        const equibopGitHash = tryOrElse(() => VesktopNative.app.getGitHash?.(), null);
        const spoofInfo = tryOrElse(() => VesktopNative.app.getPlatformSpoofInfo?.(), null);
        const isDevBuild = tryOrElse(() => VesktopNative.app.isDevBuild?.(), false);
        const shortHash = equibopGitHash?.slice(0, 7);
        return {
            name: "Equibop",
            version: VesktopNative.app.getVersion(),
            spoofed: spoofInfo?.spoofed ? `${platformName()} (spoofed from ${spoofInfo.originalPlatform})` : null,
            dev: isDevBuild,
            shortHash: shortHash,
            hash: equibopGitHash,
        };
    }

    if ("legcord" in window) return {
        name: "LegCord",
        version: window.legcord.version,
    };

    if ("goofcord" in window) return {
        name: "GoofCord",
        version: window.goofcord.version,
    };

    const name = typeof unsafeWindow !== "undefined" ? "UserScript" : "Web";
    return {
        name: name,
        info: navigator.userAgent
    };
}

async function generateDebugInfoMessage() {
    const { RELEASE_CHANNEL } = window.GLOBAL_ENV;

    const clientInfo = detectClient();
    let clientString = `${clientInfo.name}`;
    clientString += `${clientInfo.version ? ` v${clientInfo.version}` : ""}`;
    clientString += `${clientInfo.info ? ` • ${clientInfo.info}` : ""}`;
    clientString += `${clientInfo.shortHash ? ` • [${clientInfo.shortHash}](<https://github.com/Equicord/Equibop/commit/${clientInfo.hash}>)` : ""}`;

    const spoofInfo = IS_EQUIBOP ? tryOrElse(() => VesktopNative.app.getPlatformSpoofInfo?.(), null) : null;
    const platformDisplay = spoofInfo?.spoofed
        ? `${platformName()} (spoofed from ${spoofInfo.originalPlatform})`
        : platformName();

    const info = {
        Equicord:
            `v${VERSION} • [${gitHashShort}](<https://github.com/Equicord/Equicord/commit/${gitHash}>)` +
            `${IS_EQUIBOP ? "" : SettingsPlugin.getVersionInfo()} - ${Intl.DateTimeFormat("en-US", { dateStyle: "medium" }).format(BUILD_TIMESTAMP)}`,
        Client: `${RELEASE_CHANNEL} ~ ${clientString}`,
        Platform: platformDisplay
    };

    if (IS_DISCORD_DESKTOP) {
        info["Last Crash Reason"] = (await tryOrElse(() => DiscordNative.processUtils.getLastCrash(), undefined))?.rendererCrashReason ?? "N/A";
    }

    const potentiallyProblematicPlugins = ([
        "NoRPC", "NoProfileThemes", "NoMosaic", "NoRoleHeaders", "NoSystemBadge",
        "AlwaysAnimate", "ClientTheme", "SoundTroll", "Ingtoninator", "NeverPausePreviews",
        "IdleAutoRestart",
    ].filter(isPluginEnabled) ?? []).sort();

    if (isPluginEnabled(customIdle.name) && customIdle.settings.store.idleTimeout === 0) {
        potentiallyProblematicPlugins.push(customIdle.name);
    }

    const potentiallyProblematicPluginsNote = "-# Note: These plugins might not be the cause of your problem. They are simply plugins that cause common issues.";

    const commonIssues = {
        "Activity Sharing Disabled": tryOrElse(() => !ShowCurrentGame.getSetting(), false),
        "Link Embeds Disabled": tryOrElse(() => !ShowEmbeds.getSetting(), false),
        "Equicord DevBuild": !IS_STANDALONE,
        "Equibop DevBuild": IS_EQUIBOP && tryOrElse(() => VesktopNative.app.isDevBuild?.(), false),
        "Platform Spoofed": spoofInfo?.spoofed ?? false,
        "Has UserPlugins": Object.values(PluginMeta).some(m => m.userPlugin),
        ">2 Weeks Outdated": BUILD_TIMESTAMP < Date.now() - 12096e5,
        [`Potentially Problematic Plugins: ${potentiallyProblematicPlugins.join(", ")}\n${potentiallyProblematicPluginsNote}`]: potentiallyProblematicPlugins.length
    };

    let content = `>>> ${Object.entries(info).map(([k, v]) => `**${k}**: ${v}`).join("\n")}`;
    content += "\n" + Object.entries(commonIssues)
        .filter(([, v]) => v).map(([k]) => `⚠️ ${k}`)
        .join("\n");

    return content.trim();
}

async function uploadPluginListFile(channelId: string, fileContent: string, filename: string) {
    const file = new File([fileContent], filename, { type: "text/plain" });
    const upload = new CloudUploader({ file, platform: CloudUploadPlatform.WEB }, channelId);

    return new Promise<void>((resolve, reject) => {
        upload.on("complete", () => {
            RestAPI.post({
                url: Constants.Endpoints.MESSAGES(channelId),
                body: {
                    flags: 0,
                    channel_id: channelId,
                    content: `⚠️ Plugin list attached as file due to high plugin count (${fileContent.split("\n").filter(l => l.startsWith("  -")).length} plugins enabled)`,
                    nonce: SnowflakeUtils.fromTimestamp(Date.now()),
                    sticker_ids: [],
                    type: 0,
                    attachments: [{
                        id: "0",
                        filename: upload.filename,
                        uploaded_filename: upload.uploadedFilename,
                    }],
                }
            }).then(() => resolve()).catch(reject);
        });

        upload.on("error", () => reject(new Error("Failed to upload file")));

        upload.upload();
    });
}

function generatePluginList() {
    const isApiPlugin = (plugin: string) => plugin.endsWith("API") || plugins[plugin].required;

    const enabledPlugins = Object.keys(plugins)
        .filter(p => isPluginEnabled(p) && !isApiPlugin(p));

    const enabledStockPlugins = enabledPlugins.filter(p => !PluginMeta[p].userPlugin).sort();
    const enabledUserPlugins = enabledPlugins.filter(p => PluginMeta[p].userPlugin).sort();

    const user = UserStore.getCurrentUser();

    if (enabledPlugins.length > 100 && !isAnyPluginDev(user.id)) {
        Alerts.show({
            title: t("تحذير: عدد إضافات مرتفع", "Warning: High Plugin Count"),
            body: <div>
                <div style={{ display: "flex", justifyContent: "center", marginBottom: "1rem" }}>
                    <img src="https://media.tenor.com/QtGqjwBpRzwAAAAi/wumpus-dancing.gif" />
                </div>
                <Paragraph>{t("لديك أكثر من 100 إضافة مُفعّلة.", "You have more than 100 plugins enabled.")}</Paragraph>
                <Paragraph>{t("بسبب الكمّ الهائل من الإضافات، قد لا تتلقّى دعماً.", "Due to the sheer amount of plugins, you may not receive support.")}</Paragraph>
                <Paragraph>{t("مشكلتك على الأرجح ناتجة عن تعارض الإضافات.", "Your issue is likely caused by plugin conflicts.")}</Paragraph>
                <Paragraph>{t("يُرجى التفكير في تعطيل بعض الإضافات لاستكشاف المشكلة.", "Please consider disabling some plugins to troubleshoot.")}</Paragraph>
                <Paragraph className={Margins.top8}>{t("ستُرسَل قائمة إضافاتك كملف نصّي.", "Your plugin list will be sent as a text file.")}</Paragraph>
            </div>
        });

        const fileContent = [
            `Enabled Stock Plugins (${enabledStockPlugins.length}):`,
            ...enabledStockPlugins.map(p => `  - ${p}`),
            "",
        ];

        if (enabledUserPlugins.length) {
            fileContent.push(
                `Enabled User Plugins (${enabledUserPlugins.length}):`,
                ...enabledUserPlugins.map(p => `  - ${p}`),
                ""
            );
        }

        fileContent.push(
            "---",
            `Total Enabled Plugins: ${enabledPlugins.length}`,
            "Warning: Due to the high number of enabled plugins, support may be limited."
        );

        return {
            uploadFile: true,
            fileContent: fileContent.join("\n"),
            filename: `${user.username}-plugins.txt`
        };
    }

    let content = `**Enabled Plugins (${enabledStockPlugins.length}):**\n${makeCodeblock(enabledStockPlugins.join(", "))}`;

    if (enabledUserPlugins.length) {
        content += `**Enabled UserPlugins (${enabledUserPlugins.length}):**\n${makeCodeblock(enabledUserPlugins.join(", "))}`;
    }

    return content;
}

const checkForUpdatesOnce = onlyOnce(checkForUpdates);

const settings = definePluginSettings({}).withPrivateSettings<{
    dismissedDevBuildWarning?: boolean;
}>();

function DevBuildConfirmModal(props: RenderModalProps) {
    const s = settings.use(["dismissedDevBuildWarning"]);

    return (
        <ConfirmModal
            {...props}
            title={t("تمهّل!", "Hold on!")}
            confirmText="Understood"
            variant="primary"
            checkboxProps={{
                checked: s.dismissedDevBuildWarning === true,
                onChange: checked => s.dismissedDevBuildWarning = checked
            }}
        >
            <div>
                <Paragraph>{t("أنت تستخدم إصداراً مخصّصاً من Equicord، ولا نقدّم له الدعم!", "You are using a custom build of Equicord, which we do not provide support for!")}</Paragraph>

                <Paragraph className={Margins.top8}>
                    We only provide support for <Link href="https://equicord.org/download">{t("الإصدارات الرسمية", "official builds")}</Link>.
                    Either <Link href="https://equicord.org/download">{t("التبديل إلى إصدار رسمي", "switch to an official build")}</Link> or figure your issue out yourself.
                </Paragraph>

                <Text variant="text-md/bold" className={Margins.top8}>{t("ستُحظر من تلقّي الدعم إن تجاهلت هذه القاعدة.", "You will be banned from receiving support if you ignore this rule.")}</Text>
            </div>
        </ConfirmModal>
    );
}

export default definePlugin({
    name: "SupportHelper",
    required: true,
    description: "Helps us help you",
    authors: [Devs.Ven],
    dependencies: ["UserSettingsAPI", "CommandsAPI", "MessageAccessoriesAPI"],
    tags: ["Utility"],

    settings,

    patches: [{
        find: "#{intl::BEGINNING_DM}",
        replacement: {
            match: /#{intl::BEGINNING_DM},{.+?}\),(?=.{0,300}(\i)\.isMultiUserDM)/,
            replace: "$& $self.renderContributorDmWarningCard({ channel: $1 }),"
        }
    }],

    commands: [
        {
            name: "equicord-debug",
            description: t("إرسال معلومات تشخيص Equicord", "Send Equicord debug info"),
            // @ts-ignore
            predicate: ctx => isAnyPluginDev(UserStore.getCurrentUser()?.id) || isEquicordGuild(ctx?.guild?.id, true),
            execute: async () => ({ content: await generateDebugInfoMessage() })
        },
        {
            name: "equicord-plugins",
            description: t("إرسال قائمة إضافات Equicord", "Send Equicord plugin list"),
            // @ts-ignore
            predicate: ctx => isAnyPluginDev(UserStore.getCurrentUser()?.id) || isEquicordGuild(ctx?.guild?.id, true),
            execute: async () => {
                const channelId = SelectedChannelStore.getChannelId();
                const pluginList = generatePluginList();

                if (typeof pluginList === "string") {
                    return { content: pluginList };
                } else if (pluginList && typeof pluginList === "object" && pluginList.uploadFile) {
                    try {
                        await uploadPluginListFile(channelId, pluginList.fileContent, pluginList.filename);
                        return { content: "" }; // Empty return since file was already sent
                    } catch (e) {
                        new Logger("SupportHelper").error("Failed to upload plugin list:", e);
                        return { content: t("فشل رفع ملف قائمة الإضافات. حاول مرّة أخرى.", "Failed to upload plugin list file. Please try again.") };
                    }
                }
                return { content: t("تعذّر إنشاء قائمة الإضافات.", "Unable to generate plugin list.") };
            }
        }
    ],

    flux: {
        async CHANNEL_SELECT({ channelId }) {
            const isSupportChannel = SUPPORT_CHANNEL_IDS.includes(channelId);
            if (!isSupportChannel) return;

            const selfId = UserStore.getCurrentUser()?.id;
            if (!selfId || isAnyPluginDev(selfId)) return;

            if (!IS_UPDATER_DISABLED) {
                await checkForUpdatesOnce().catch(() => { });

                if (isOutdated) {
                    openModal(props => (
                        <ConfirmModal
                            {...props}
                            variant="primary"
                            title={t("تمهّل!", "Hold on!")}
                            confirmText={t("تحديث وإعادة تشغيل الآن", "Update & Restart Now")}
                            cancelText={t("عرض التحديثات", "View Updates")}
                            onConfirm={forceUpdate}
                            onCancel={() => openSettingsTabModal(UpdaterTab!)}
                        >
                            <div>
                                <Paragraph>{t("أنت تستخدم إصداراً قديماً من Equicord! غالباً مشكلتك مُصلَحة بالفعل.", "You are using an outdated version of Equicord! Chances are, your issue is already fixed.")}</Paragraph>
                                <Paragraph className={Margins.top8}>{t("يُرجى التحديث أولاً قبل طلب الدعم!", "Please first update before asking for support!")}</Paragraph>
                                <Paragraph className={Margins.top8}>{t("إن كنت تعرف ما تفعله أو لا يمكنك التحديث، يمكنك تجاهل هذا التنبيه.", "If you know what you're doing or cannot update, you can dismiss this prompt.")}</Paragraph>
                            </div>
                        </ConfirmModal>
                    ));
                    return;
                }
            }

            const roles = GuildMemberStore.getSelfMember(VC_GUILD_ID)?.roles || GuildMemberStore.getSelfMember(GUILD_ID)?.roles;
            if (!roles || TrustedRolesIds.some(id => roles.includes(id))) return;

            if (!IS_WEB && IS_UPDATER_DISABLED) {
                openModal(props => (
                    <ConfirmModal
                        {...props}
                        title={t("تمهّل!", "Hold on!")}
                        confirmText="OK"
                        variant="primary"
                    >
                        <div>
                            <Paragraph>{t("أنت تستخدم إصدار Equicord مُحدَّثاً خارجياً، ولا نقدّم له الدعم!", "You are using an externally updated Equicord version, which we do not provide support for!")}</Paragraph>
                            <Paragraph className={Margins.top8}>
                                Please either switch to an <Link href="https://equicord.org/download">{t("إصدار Equicord المدعوم رسمياً", "officially supported version of Equicord")}</Link>, or
                                contact your package maintainer for support instead.
                            </Paragraph>
                        </div>
                    </ConfirmModal>
                ));
                return;
            }

            if (!IS_STANDALONE && !settings.store.dismissedDevBuildWarning) {
                openModal(props => <DevBuildConfirmModal {...props} />);
                return;
            }
        }
    },

    renderMessageAccessory(props) {
        const buttons = [] as JSX.Element[];

        const equicordSupport = isEquicordSupport(props.message.author.id);

        const shouldAddUpdateButton =
            !IS_UPDATER_DISABLED
            && ((isSupportChannel(props.channel.id) && equicordSupport))
            && props.message.content?.toLowerCase().includes("update");

        if (shouldAddUpdateButton) {
            buttons.push(
                <Button
                    key="vc-update"
                    variant="positive"
                    onClick={async () => {
                        try {
                            if (await forceUpdate())
                                showToast(t("نجح! جارٍ إعادة التشغيل...", "Success! Restarting..."), Toasts.Type.SUCCESS);
                            else
                                showToast(t("محدَّث بالفعل!", "Already up to date!"), Toasts.Type.MESSAGE);
                        } catch (e) {
                            new Logger(this.name).error("Error while updating:", e);
                            showToast(t("فشل التحديث :(", "Failed to update :("), Toasts.Type.FAILURE);
                        }
                    }}
                >{t("حدّث الآن", "Update Now")}</Button>
            );
        }

        if (equicordSupport && isSupportChannel(props.channel.id) && PermissionStore.can(PermissionsBits.SEND_MESSAGES, props.channel)) {
            if (props.message.content.includes("/equicord-debug") || props.message.content.includes("/equicord-plugins")) {
                buttons.push(
                    <Button
                        key="vc-dbg"
                        variant="secondary"
                        onClick={async () => sendMessage(props.channel.id, { content: await generateDebugInfoMessage() })}
                    >
                        Run /equicord-debug
                    </Button>,
                    <Button
                        key="vc-plg-list"
                        variant="secondary"
                        onClick={async () => {
                            const pluginList = generatePluginList();
                            if (typeof pluginList === "string") {
                                sendMessage(props.channel.id, { content: pluginList });
                            } else if (pluginList && typeof pluginList === "object" && pluginList.uploadFile) {
                                try {
                                    await uploadPluginListFile(props.channel.id, pluginList.fileContent, pluginList.filename);
                                    showToast(t("تمّ رفع قائمة الإضافات بنجاح!", "Plugin list uploaded successfully!"), Toasts.Type.SUCCESS);
                                } catch (e) {
                                    new Logger("SupportHelper").error("Failed to upload plugin list:", e);
                                    showToast(t("فشل رفع قائمة الإضافات", "Failed to upload plugin list"), Toasts.Type.FAILURE);
                                }
                            }
                        }}
                    >
                        Run /equicord-plugins
                    </Button>
                );
            }
        }

        if (equicordSupport || (isSupportChannel(props.channel.id) || isKnownIssuesCategory(props.channel.parent_id))) {
            const match = CodeBlockRe.exec(props.message.content || props.message.embeds[0]?.rawDescription || "");
            if (match) {
                buttons.push(
                    <Button
                        key="vc-run-snippet"
                        onClick={async () => {
                            try {
                                const result = await AsyncFunction(match[1])();
                                const stringed = String(result);
                                if (stringed) {
                                    await sendBotMessage(SelectedChannelStore.getChannelId(), {
                                        content: stringed
                                    });
                                }

                                showToast(t("نجح!", "Success!"), Toasts.Type.SUCCESS);
                            } catch (e) {
                                new Logger(this.name).error("Error while running snippet:", e);
                                showToast(t("فشل تشغيل المقتطف :(", "Failed to run snippet :("), Toasts.Type.FAILURE);
                            }
                        }}
                    >
                        {t("تشغيل المقتطف", "Run Snippet")}
                    </Button>
                );
            }
        }

        return buttons.length
            ? <Flex>{buttons}</Flex>
            : null;
    },

    renderContributorDmWarningCard: ErrorBoundary.wrap(({ channel }) => {
        const userId = channel.getRecipientId();
        if (!isAnyPluginDev(userId)) return null;
        if (RelationshipStore.isFriend(userId) || isAnyPluginDev(UserStore.getCurrentUser()?.id)) return null;

        const esharqSupportChannelId = "1502719959485255922";
        const esharqSupportLink = "https://discord.com/channels/1211352550583042058/1502719959485255922";

        return (
            <Card variant="warning" className={Margins.top8} defaultPadding>
                {t(
                    "الرجاء عدم مراسلة مطوّري اشراق برسائل خاصّة طلباً للدعم!",
                    "Please do not private message Esharq developers for support!"
                )}
                <br />
                {t("بدلاً من ذلك، استخدم قناة الدعم:", "Instead, use the support channel:")}{" "}
                {Parser.parse(esharqSupportLink)}
                {!ChannelStore.getChannel(esharqSupportChannelId) && t(" (اضغط الرابط للانضمام)", " (Click the link to join)")}
            </Card>
        );
    }, { noop: true }),
});
