import { Paragraph } from "@components/Paragraph";
import { t } from "@utils/esharqI18n";
import { Modal } from "@webpack/common";

import { ClearAliasesConfirmModalProps } from "./types";

export function ClearAliasesConfirmModal({ modalProps, onConfirm }: ClearAliasesConfirmModalProps) {
    return (
        <Modal
            {...modalProps}
            size="sm"
            title={t("حذف كل الأسماء المستعارة", "Delete all aliases")}
            actions={[
                {
                    text: t("حذف كل الأسماء المستعارة", "Delete all aliases"),
                    variant: "danger-primary",
                    onClick: async () => {
                        await onConfirm();
                        modalProps.onClose();
                    }
                }
            ]}
        >
            <Paragraph>{t("سيؤدّي هذا إلى إزالة كل اسم مستعار للإيموجي حفظته.", "This will remove every emoji alias you saved.")}</Paragraph>
        </Modal>
    );
}
