function getEffectiveList(): string[] {
    if (settings.store.defaultHidden) {
        if (!settings.store.disabledLocations) {
            settings.store.disabledLocations = "";
            return [];
        } else {
            return settings.store.disabledLocations.split(",").map(x => x.trim()).filter(Boolean);
        }
    } else {
        if (!settings.store.enabledLocations) {
            settings.store.enabledLocations = "";
            return [];
        } else {
            return settings.store.enabledLocations.split(",").map(x => x.trim()).filter(Boolean);
        }
    }
}

function isImplicitlyAllowed(channel: string | Channel): number {
    const resolvedChannel = typeof channel === "string" ? ChannelStore.getChannel(channel) : channel;

    if (!resolvedChannel) {
        return 0;
    }

    const connectedVoiceChannelID = SelectedChannelStore.getVoiceChannelId();
    const guildID = resolvedChannel.guild_id;

    if (settings.store.alwaysEnableInActiveVoiceChat && connectedVoiceChannelID === resolvedChannel.id) {
        return 1;
    }

    const addedThreshold = !guildID
        ? settings.store.temporaryEnableThresholdDirectMessages
        : settings.store.temporaryEnableThresholdServers;

    if (addedThreshold === 0) {
        return 0;
    }

    const lastMessage = MessageStore.getLastEditableMessage(resolvedChannel.id);
    const messageTimestamp = lastMessage?.timestamp?.getTime?.();

    if (messageTimestamp && Date.now() < messageTimestamp + (addedThreshold * 1000)) {
        return 2;
    }

    return 0;
}

function isExplicitlyDisallowed(channel: string | Channel): boolean {
    if (!settings.store.enabledGlobally) return false;

    const channelID = typeof channel === "string" ? channel : channel.id;
    const guildID = typeof channel === "string" ? ChannelStore.getChannel(channelID)?.guild_id : channel.guild_id;
    const effectiveChannels = getEffectiveList();

    if (settings.store.defaultHidden) {
        return !effectiveChannels.includes(guildID) && !effectiveChannels.includes(channelID);
    } else {
        return effectiveChannels.includes(guildID) || effectiveChannels.includes(channelID);
    }
}

const ChatBarContextCheckbox: NavContextMenuPatchCallback = children => {
    const {
        chatIcon,
        chatContextMenu,
        enabledGlobally,
        defaultHidden,
        hideChatBoxTypingIndicators,
        hideMembersListTypingIndicators
    } = settings.use([
        "chatIcon",
        "chatContextMenu",
        "enabledGlobally",
        "defaultHidden",
        "hideChatBoxTypingIndicators",
        "hideMembersListTypingIndicators"
    ]);

    if (!chatContextMenu) return;

    const group = findGroupChildrenByChildId("submit-button", children as (React.ReactElement | null | undefined)[]);

    if (!group) return;

    const idx = group.findIndex(c => c?.props?.id === "submit-button");

    group.splice(idx >= 0 ? idx : 0, 0,
        <Menu.MenuItem id="vc-silent-typing" label="Silent Typing">
            <Menu.MenuCheckboxItem id="vc-silent-typing-enabled" label={t("مُفعَّل", "Enabled")} checked={enabledGlobally}
                action={() => settings.store.enabledGlobally = !settings.store.enabledGlobally} />
            <Menu.MenuCheckboxItem id="vc-silent-typing-chat-bar-indicators" label={t("مؤشّرات شريط الدردشة", "Chat Bar Indicators")} checked={settings.store.hideChatBoxTypingIndicators}
                action={() => settings.store.hideChatBoxTypingIndicators = !settings.store.hideChatBoxTypingIndicators} />
            <Menu.MenuCheckboxItem id="vc-silent-typing-members-list-indicators" label={t("مؤشّرات قائمة الأعضاء", "Members List Indicators")} checked={settings.store.hideMembersListTypingIndicators}
                action={() => settings.store.hideMembersListTypingIndicators = !settings.store.hideMembersListTypingIndicators} />
            <Menu.MenuCheckboxItem id="vc-silent-typing-chat-icon" label={t("أيقونة الدردشة", "Chat Icon")} checked={chatIcon}
                action={() => settings.store.chatIcon = !settings.store.chatIcon} />
            <Menu.MenuCheckboxItem id="vc-silent-typing-default" label={t("مخفي افتراضياً", "Default Hidden")} checked={defaultHidden}
                action={() => settings.store.defaultHidden = !settings.store.defaultHidden} />
        </Menu.MenuItem>
    );
};

function shouldHideChatBarTypingIndicators(): boolean {
    const { hideChatBoxTypingIndicators } = settings.use(["hideChatBoxTypingIndicators"]);
    return hideChatBoxTypingIndicators;
}

function shouldHideMembersListTypingIndicators(): boolean {
    const { hideMembersListTypingIndicators } = settings.use(["hideMembersListTypingIndicators"]);
    return hideMembersListTypingIndicators;
}

export default definePlugin({
    name: "SilentTyping",
    authors: [Devs.Ven, Devs.Rini, Devs.ImBanana, EquicordDevs.Etorix],
    description: "Prevents your typing indicator from showing to others",
    dependencies: ["CommandsAPI", "ChatInputButtonAPI"],
    tags: ["Chat", "Privacy"],
    isModified: true,
    settings,

    shouldHideChatBarTypingIndicators,
    shouldHideMembersListTypingIndicators,

    contextMenus: {
        "textarea-context": ChatBarContextCheckbox
    },

    chatBarButton: {
        icon: SilentTypingChatIcon,
        render: SilentTypingChatToggle
    },

    flux: {
        VOICE_STATE_UPDATES({ voiceStates }) {
            const state = voiceStates?.[0];

            if (!state) {
                return;
            }

            if (state.userId !== UserStore.getCurrentUser().id) {
                return;
            }

            if (state.channelId === state.oldChannelId) {
                return;
            }

            if (settings.store.alwaysEnableInActiveVoiceChat) {
                triggerChatToggleRerender();
            }
        },

        MESSAGE_CREATE({ message }) {
            if (message.author.id === UserStore.getCurrentUser().id) {
                const threshold = message.guild_id
                    ? settings.store.temporaryEnableThresholdServers
                    : settings.store.temporaryEnableThresholdDirectMessages;

                if (threshold > 0) {
                    triggerChatToggleRerender();

                    setTimeout(() => {
                        triggerChatToggleRerender();
                    }, (threshold * 1000) + 25);
                }
            }
        }
    },

    patches: [
        {
            find: '.dispatch({type:"TYPING_START_LOCAL"',
            replacement: {
                match: /startTyping\(\i\){.+?},stop/,
                replace: "startTyping:$self.startTyping,stop"
            }
        },
        {
            find: "activityInviteEducationActivity:",
            group: true,
            replacement: [
                {
                    match: /(let{activityInviteEducationActivity)/,
                    replace: "const silentTypingShouldHideChatBarTypingIndicators=$self.shouldHideChatBarTypingIndicators();$1"
                },
                {
                    match: /("stop-animation".{0,80}?ref:\i,children:)/,
                    replace: "$1silentTypingShouldHideChatBarTypingIndicators?[]:"
                }
            ]
        },
        {
            find: ",{avatarCutoutX",
            replacement: {
                match: /isTyping:(\i)=!1(,typingIndicatorRef:\i,isSpeaking:)/,
                replace: "silentTypingIsTyping:$1=$self.shouldHideMembersListTypingIndicators()?false:(arguments[0].isTyping??false)$2"
            }
        },
    ],

    commands: [
        {
            name: "silent-typing",
            description: t("إخفاء مؤشر الكتابة عن الدردشة.", "Hide the typing indicator from the chat."),
            inputType: ApplicationCommandInputType.BUILT_IN,

            options: [
                {
                    name: "toggle",
                    description: t("تبديل الوظيفة عالمياً أو للقناة أو للسيرفر.", "Toggle the feature globally, for the channel, or for the server."),
                    required: false,
                    type: ApplicationCommandOptionType.STRING,
                    choices: [
                        { name: "Global", label: t("عام", "Global"), value: "global" },
                        { name: "Channel", label: t("القناة", "Channel"), value: "channel" },
                        { name: "Guild", label: t("الخادم", "Guild"), value: "guild" },
                    ]
                },
                {
                    name: "chat-bar-indicators",
                    description: t("إخفاء مؤشرات الكتابة للمستخدمين الآخرين من فوق شريط الدردشة.", "Hide typing indicators for other users from above the chat bar."),
                    required: false,
                    type: ApplicationCommandOptionType.BOOLEAN,
                },
                {
                    name: "members-list-indicators",
                    description: t("إخفاء مؤشرات الكتابة للمستخدمين الآخرين من قائمة الأعضاء.", "Hide typing indicators for other users from the member list."),
                    required: false,
                    type: ApplicationCommandOptionType.BOOLEAN,
                },
                {
                    name: "chat-icon",
                    description: t("إظهار أيقونة في شريط الدردشة لتبديل الإضافة أثناء الاستخدام.", "Show an icon in the chat bar to toggle the plugin on the fly."),
                    required: false,
                    type: ApplicationCommandOptionType.BOOLEAN,
                },
                {
                    name: "chat-context-menu",
                    description: t("إظهار قائمة منسدلة في قائمة سياق الدردشة لتبديل إعدادات الإضافة.", "Show a submenu in the chat context menu to toggle plugin settings."),
                    required: false,
                    type: ApplicationCommandOptionType.BOOLEAN,
                },
                {
                    name: "default-hidden",
                    description: t("تحديد ما إذا كان سيتم إخفاء الكتابة في الرسائل المباشرة/القنوات/السيرفرات افتراضياً.", "Determine whether typing will be hidden in DMs/channels/servers by default."),
                    required: false,
                    type: ApplicationCommandOptionType.BOOLEAN,
                }
            ],

            execute: async (args, ctx) => {
                let updated = false;
                const location = findOption(args, "toggle");

                if (typeof location === "string") {
                    updated = true;

                    if (location === "global") {
                        toggleGlobal();
                    } else {
                        const locationId = location === "guild" ? ctx.channel.guild_id : ctx.channel.id;
                        toggleLocation(locationId, getEffectiveList(), settings.store.defaultHidden);
                    }
                }

                const updateChatIcon = findOption(args, "chat-icon");

                if (typeof updateChatIcon === "boolean") {
                    updated = true;
                    settings.store.chatIcon = !!updateChatIcon;
                }

                const updateChatContextMenu = findOption(args, "chat-context-menu");

                if (typeof updateChatContextMenu === "boolean") {
                    updated = true;
                    settings.store.chatContextMenu = !!updateChatContextMenu;
                }

                const updateDefaultHidden = findOption(args, "default-hidden");

                if (typeof updateDefaultHidden === "boolean") {
                    updated = true;
                    settings.store.defaultHidden = !!updateDefaultHidden;
                }

                sendBotMessage(ctx.channel.id, {
                    content: updated ? "Silent typing settings updated." : "No changes made to silent typing settings.",
                });
            },
        }
    ],

    async startTyping(channelId: string) {
        if (isExplicitlyDisallowed(channelId) && !isImplicitlyAllowed(channelId)) {
            return;
        }

        FluxDispatcher.dispatch({ type: "TYPING_START_LOCAL", channelId });
    },
});
