(window.VencordStyles ??= new Map()).set("src/userplugins/lazyMessageRender/style.css", {
    name: "src/userplugins/lazyMessageRender/style.css",
    source: "/* content-visibility أُزيل: مُقطِّع ديسكورد الافتراضي (virtualized scroller) يُخطئ قياس\n * الصفوف المحتواة بعد تحديثاته، فيسبّب قفز التمرير عند المرور على الرسالة وقصّ شريط\n * الأدوات. نُبقي فقط رفع الطبقة (z-index) كي لا يُقصّ شريط الأدوات تحت الرسالة الأعلى. */\n\n[--messageListItem]:hover,\n[--messageListItem]:focus-within {\n    position: relative;\n    z-index: 2;\n}\n\n[--messageListItem]:hover + [--messageListItem],\n[--messageListItem]:focus-within + [--messageListItem],\n[--messageListItem]:has(+ [--messageListItem]:hover),\n[--messageListItem]:has(+ [--messageListItem]:focus-within) {\n    z-index: 1;\n}\n",
    classNames: {},
    dom: null,
});

export default "src/userplugins/lazyMessageRender/style.css";
